        int b = Integer.parseInt(parts[1]);
        if (a > b) {
            int temp = a;
            a = b;
            b = temp;
        }
        int c = 7 - b;
        int g = gcd(c, 6);
        System.out.println((c / g) + "/" + (6 / g));
    }

    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

